    for i in range(n):
        if not stack or a[i] >= stack[-1]:
            stack.append(a[i])
        else:
            break

    if len(stack) == n:
        return "NO"

    inc_seq = stack[:]
    dec_seq = []
    while i < n:
        if a[i] <= dec_seq[-1]:
            dec_seq.append(a[i])
        else:
            return "NO"
        i += 1

    return "YES\n{}\n{}\n{}\n{}".format(len(inc_seq), ' '.join(map(str, inc_seq)), len(dec_seq), ' '.join(map(str, dec_seq[::-1])))

