    max_val = -float('inf')
    break_point = -1

    for i in range(1, n):
        if a[i] < a[i - 1]:
            if break_point == -1:
                break_point = i
            else:
                return "NO"
        elif a[i] > a[i - 1]:
            min_val = min(min_val, a[i])

    if break_point == -1:
        return "NO"

    inc_seq = [a[i] for i in range(break_point)]
    dec_seq = [a[i] for i in range(break_point, n) if a[i] <= min_val]

    if len(dec_seq) != n - break_point:
        return "NO"

    return "YES\n{}\n{}\n{}\n{}".format(len(inc_seq), *inc_seq, len(dec_seq), *dec_seq)

